<?php if(($data['products']??[])===[]): ?><div class="empty-state"><span class="empty-mark" aria-hidden="true">A</span><h3><?= !empty($data['search'])?'কোনো পণ্য মেলেনি':'পণ্য যোগ হলেই এখানে দেখা যাবে' ?></h3><p><?= !empty($data['search'])?'অন্য শব্দ দিয়ে খুঁজে দেখুন, অথবা সব পণ্য দেখুন।':'আপনার Supabase catalog-এ active product যোগ করুন—স্টোরফ্রন্টে স্বয়ংক্রিয়ভাবে দেখাবে।' ?></p><?php if(!empty($data['search'])): ?><a class="text-link" href="/shop">সব পণ্য দেখুন →</a><?php endif; ?></div><?php else: ?><div class="product-grid"><?php foreach($data['products'] as $product): $image=trim((string)($product['image_url']??''))?:asset('category-tech.jpg'); ?><article class="product-card"><a class="product-image" href="/product/<?= rawurlencode((string)$product['slug']) ?>"><img src="<?= e($image) ?>" alt="<?= e($product['name']) ?>" loading="lazy"><?php if(!empty($product['is_featured'])): ?><span class="product-badge">বাছাই</span><?php endif; ?></a><div class="product-info"><?php if(!empty($product['category_name'])): ?><span class="product-category"><?= e($product['category_name']) ?></span><?php endif; ?><h3><a href="/product/<?= rawurlencode((string)$product['slug']) ?>"><?= e($product['name']) ?></a></h3><?php if(!empty($product['short_description'])): ?><p><?= e($product['short_description']) ?></p><?php endif; ?><div class="product-bottom"><span class="price"><?= e(format_price((float)$product['price'],$product['currency']??null)) ?></span><?php if(($product['product_type']??'simple')==='simple'&&(int)$product['stock_quantity']>0): ?><form action="/cart/add" method="post"><?= csrf_field() ?><input type="hidden" name="product_id" value="<?= e($product['id']) ?>"><button class="quick-add" type="submit" aria-label="<?= e($product['name']) ?> ব্যাগে যোগ করুন">+</button></form><?php else: ?><a class="text-link" href="/product/<?= rawurlencode((string)$product['slug']) ?>">বিস্তারিত →</a><?php endif; ?></div><?php if(!empty($data['account'])): ?><form action="/account/wishlist" method="post" class="wishlist-card-form"><?= csrf_field() ?><input type="hidden" name="product_id" value="<?= e($product['id']) ?>"><input type="hidden" name="return_to" value="<?= e($_SERVER['REQUEST_URI']??'/shop') ?>"><button class="text-link" type="submit">♡ Wishlist</button></form><?php endif; ?></div></article><?php endforeach; ?></div><?php endif; ?>
